def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    current_group = []
    stack = []

    for char in paren_string:
        if char == "(":
            stack.append(char)
            current_group.append(char)
        elif char == ")":
            current_group.append(char)
            stack.pop()
            if not stack:
                groups.append("".join(current_group))
                current_group.clear()

    if current_group:
        raise ValueError("The input string is not balanced")

    return groups

