def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Iterate over each element in the grid
    for x, y, value in grid_values:
        # If the element is not the last element in the grid
        if x != N or y != N:
            # Update the dynamic programming table
            dp[x][y] = max(dp[x][y], dp[x - 1][y - 1], dp[x - 1][y], dp[x][y - 1]) + value
        else:
            # If the element is the last element in the grid, simply add its value
            dp[x][y] = dp[x - 1][y - 1] + value

    # Return the maximum sum of values collected on the two paths
    return max(dp[N][N], dp[N][N - 1], dp[N - 1][N])

