def max_value_on_paths(N, grid_values):
    # Initialize a 2D array to store the maximum sum of values collected on each path
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Initialize a 2D array to store the coordinates of the cells on each path
    path = [[(0, 0)] * (N + 1) for _ in range(N + 1)]

    # Populate the first row and column of the dp and path arrays with the values from the grid
    for i, j, val in grid_values:
        dp[i][j] = val
        path[i][j] = (i, j)

    # Calculate the maximum sum of values collected on each path
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + grid_values[i][j]
            if dp[i][j] > dp[i - 1][j - 1]:
                path[i][j] = (i, j)
            else:
                path[i][j] = path[i - 1][j - 1]

    # Find the maximum sum of values collected on the two paths
    max_sum = 0
    for i, j in [(0, 0), (N, N)]:
        while path[i][j] != (i, j):
            max_sum += grid_values[i][j]
            i, j = path[i][j]

    return max_sum

