    # Edge case: if n is 0, there is only one way to partition it into k parts
    if n == 0:
        return 1

    # Edge case: if k is 1, there is only one way to partition n into one part
    if k == 1:
        return n

    # Initialize the number of ways to partition n
    ways = 0

    # Loop through each possible partition of n into k parts
    for i in range(n):
        # Check if the current partition is valid
