def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T == 0 or M == 0:
        return 0

    # Initialize a 2D matrix to store the maximum total value of herbs that can be picked
    # within a given time limit for each possible combination of herbs to pick and time limit
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Base case: if there are no herbs or no time limit, the maximum total value is 0
    for i in range(M + 1):
        dp[i][0] = 0
    for j in range(T + 1):
        dp[0][j] = 0

    # Populate the matrix using the recurrence relation
