def next_permutation(perm):
    # Find the first number from the end that is smaller than the number following it
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break

    # If no such number is found, it means the input permutation is the last
    # permutation in descending order, so we return False
    if i == -1:
        return False

    # Find the smallest number that is larger than perm[i] and comes after it
    for j in range(i + 1, len(perm)):
        if perm[j] > perm[i]:
            break

    # Swap perm[i] with perm[j]
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the order of numbers after the original first smaller number
    perm[i + 1:] = perm[i + 1:][::-1]

    # Return True since the permutation was transformed
    return True

